"""Writes research_rig/PREREG_11_earnings_release_reader.md. Every count in it comes from events_11_summary.json
(prep_11.py summary) or extraction_check_11.json (extract_check_11.py), every setting from config/thresholds.yaml, and the
model lines are quoted from docs/research/31_model_knowledge_lines.md. Nothing is typed by hand except the words.
Usage, from research_rig/:  python3 build_prereg_11.py"""
import os, json, re
import common_11 as C

S = json.load(open(C.SUMMARY)); X = json.load(open(os.path.join(C.HERE, "extraction_check_11.json"))); SP = json.load(open(os.path.join(C.HERE, "split_check_11.json")))
EV, CO, RD, DS, GP, ST = (C.th(k) for k in ("replay_11_events", "replay_11_costs", "replay_11_readers", "replay_11_design", "replay_11_gap", "replay_11_statistics"))
NAMES = {"claude_sonnet_5_5": "Claude Sonnet 5.5", "grok_4_7": "Grok 4.7", "kimi_k3": "Kimi K3", "claude_opus_5_5": "Claude Opus 5.5"}
doc31 = open(os.path.join(C.HERE, "..", "docs", "research", "31_model_knowledge_lines.md"), encoding="utf-8").read().split("\n")
def q31(name):
    row = next(l for l in doc31 if l.startswith(f"| {name} |")); said = next(l for l in doc31 if l.startswith(f"- {name}:"))
    return row, said
def pc(x, d=1): return f"{100 * x:.{d}f}%"
def n(x): return f"{x:,}"
U, T, F, P = S["used"], S["used_total"], S["filings"], S["prices"]
LN = {"500": "S&P 500", "400": "S&P MidCap 400", "600": "S&P SmallCap 600"}
setups = DS["setups"]; nsu = len(setups); nh = len(ST["holds"])
cost = CO["bps_per_side"]; tx = S["text_chars"]; sz = S["size"]; cap = RD["text_cap_chars"]

o = []; w = o.append
w("# Pre-registration 11: an AI reads each earnings release and says buy or skip for the next open\n")
w(f"Status: frozen 2026-11-25 17:56 UTC by the lead. Built {S['made_utc'][:10]} by `build_prereg_11.py` from `events_11_summary.json`, `extraction_check_11.json` and the replay_11_* keys in `config/thresholds.yaml`. Do not edit by hand. Ledger rows 121 to 134 in `research_rig/TRIAL_LEDGER.md` were pushed in the same commit as this file, before any reader saw a release and before any return after any event was worked out. The code was audited twice by a second model before the freeze (the faults found were fixed, each with a test in `test_11.py`; one, about half-days and market holidays, is noted below and not changed). From here only faults in code may be fixed. Queue row 9b in `docs/QUEUE.md`.\n")
w("## The claim\n")
w("When a company files its quarterly results with the SEC, an AI that reads the press release can tell which stocks will do better after the next regular-session open. Only the move after that open can be traded by this desk, so only that move is judged. The jump between the filing and the open is not ours and is not counted.\n")
w("## Why now: the readers cannot know the outcome\n")
w(f"Every release used is filed on or after {EV['start']}. Each reader's knowledge line, quoted from `docs/research/31_model_knowledge_lines.md` (MEASURED on crypto month-end prices; columns: latest month it says it knows, last month it got right, replay months answered, replay months right, later hits by carrying forward):\n")
for m in RD["small_models"] + [RD["strong_model"]]:
    row, said = q31(NAMES[m]); w(f"- `{m}`: `{row}`")
    w(f"  Its own words: \"{said.split(': ', 1)[1]}\"")
w("")
w("All four lines are before 2026-04-01. The line was measured on prices, not company news. A model may still know company news from before its line; that was public before the filing, so it is fair.\n")
w("## Stock lists (MEASURED, saved before any price was read)\n")
for l in C.LISTS:
    w(f"- {LN[l]} ({l}): {S['list_sources'][l]}. {n(S['members'][l])} companies after one row per CIK.")
w(f"- CIKs: {n(S['cik_how'].get('table', 0))} from the tables, {n(S['cik_how'].get('sec ticker file', 0))} from the SEC's company_tickers.json saved 2026-11-25 (most 400 rows give a ticker, not a CIK), {n(S['cik_how'].get('edgar name search', 0))} by name with EDGAR's company search on 2026-11-25 because their tickers have left that file. Members with no CIK: {len(S['members_without_cik'])}. A CIK in two lists is kept in the first (500, 400, 600).")
w("- Wikipedia is dated but anyone can edit it. S&P's own dated lists were not found. Companies that left an index between April and November stay in (no survivorship filter).\n")
w(f"## Events (MEASURED by `fetch_11_edgar.py`, counted by `prep_11.py summary`)\n")
w(f"Every 8-K or 8-K/A with item 2.02 from these companies, filing date {EV['start']} to {EV['end']}, from `data.sec.gov/submissions`, with the SEC acceptance time to the second put in New York time. The press release is the exhibit typed EX-99.1, EX-99.01 or EX-99 on the filing's index page, else its first EX-99 of any number.\n")
w("| List | Item 2.02 filings | Companies | 8-K/A | With an EX-99 | Text at least min_text_chars | Before open | During hours | After close |")
w("|---|---|---|---|---|---|---|---|---|")
for l in C.LISTS:
    f = F[l]; s = f["session"]
    w(f"| {l} | {n(f['item_202_filings'])} | {n(f['companies_with_filings'])} | {f['amendments']} | {n(f['with_exhibit_99'])} | {n(f['text_at_least_min'])} | {n(s.get('before_open', 0))} | {n(s.get('during_hours', 0))} | {n(s.get('after_close', 0))} |")
w("")
w(f"Filters, fixed now (replay_11_events): 8-K only; exhibit text at least {EV['min_text_chars']} characters (shorter is usually a cover note); one event per company per {EV['min_days_between']} days, the first kept; a daily bar on the entry day. No filter on size, sector or the text's content.\n")
w("Dropped: " + "; ".join(f"{k} {v}" for k, v in S["dropped"].items()) + ".\n")
w("| List | Used events | Companies | Design half | Held-back half |"); w("|---|---|---|---|---|")
for l in C.LISTS: w(f"| {l} | {n(U[l]['events'])} | {n(U[l]['companies'])} | {n(U[l]['design'])} | {n(U[l]['heldback'])} |")
w(f"| all | {n(T['events'])} | | {n(T['design'])} | {n(T['heldback'])} |\n")
w(f"Split by date on all three lists pooled: the used events sorted by acceptance time, cut at the change of entry day nearest the middle by count, so that no entry day (and no open) is in both halves. The halves are therefore not exactly equal. The last design event was accepted {T['split_last_design']} New York time (entry {T['last_design_entry_day']}) and the first held-back event {T['split_first_heldback']} (entry {T['first_heldback_entry_day']}). By month: " + ", ".join(f"{k} {v}" for k, v in T["by_month"].items()) + ".\n")
w("## Prices (MEASURED, coverage only)\n")
w(f"Daily open, close and volume from the workspace's built-in price history, {P['first']} to {P['last']}, {P['trading_days']} trading days (the SPY daily file's days). Saved under `~/workspace/rig/data/stock_daily_11/`, never in the repo. Adjustment: see the next list.\n")
w(f"- Splits (MEASURED by `split_check_11.py`): {SP['splits_checked']} list members that split between {P['first']} and {P['last']}, from company filings and two split tables. " + ", ".join(f"{r['symbol']} {('1-for-' + str(round(1 / r['ratio']))) if r['ratio'] < 1 else (str(round(r['ratio'])) + '-for-1')} ({r['first_adjusted_day']})" for r in SP["rows"]) + f". In {SP['adjusted']} of {SP['splits_checked']} our file shows no jump on the split day. In {SP['close_match_within_0_2pct']} of the {SP['with_as_traded_close']} with an as-traded close before the split, our close times the ratio equals it within 0.2%. So the files are split-adjusted. Sources: [Mueller Industries 8-K exhibit](https://www.sec.gov/Archives/edgar/data/89439/000008943926000025/ex-99_16302026stocksplit.htm), [Honeywell press release](https://www.honeywell.com/us/en/news/press-releases/2026/06/honeywell-board-of-directors-sets-record-date-and-announces-expected-timing-for-spin-off-of-honeywell-aerospace-and-honeywell-reverse-stock-split), [Sandisk 8-K](https://www.stocktitan.net/sec-filings/SNDK/8-k-sandisk-corp-reports-material-event-8248455531a3.html), [StocksXray split table](https://www.stocksxray.com/stock-splits) and [Stock Titan split list](https://www.stocktitan.net/articles/stock-splits-2026-list-big-companies) (as-traded closes, STATED by those pages). No split fix is needed, so none is applied.")
w("- Dividends: the same closes match the as-traded close divided by the ratio to the cent months after the split, for companies that pay dividends (BKNG, KLAC, DD, APH), so ordinary dividends do not look adjusted out. Ex-dividend dates were not checked: STATED, not MEASURED. A trade that holds over an ex-dividend day loses the dividend; on a 5-day hold that is small and the same for set-ups and yardsticks. A special dividend would show as a large overnight move (next list).")
w("- Prices collected again for the held-back exits must be collected for every symbol at once, so all files share one adjustment date. A split between two collections would otherwise mix adjusted and unadjusted bars.")
for l in C.LISTS:
    c = P["by_list"][l]; w(f"- {l}: {c['every_day']} of {c['companies']} companies have every day. Short: " + ", ".join(f"{s} ({v['days']} days, {v['first']} to {v['last']})" for s, v in sorted(c["short"].items())) + ".")
Wn = S["windows"]; OV = C.th("replay_11_overnight")
w(f"- Used events whose stock's bars stop or start somewhere in {P['first']} to {P['last']}: {S['prices']['used_events_whose_bars_stop_before_last_day']}. Of those, the bars stop inside the event's own hold for " + ", ".join(f"{h} {v['stops_inside_total']}" for h, v in Wn["by_hold"].items()) + " (counted on dates only). A trade whose stock has no bar on the exit day sells at the last close in the file, and is flagged and counted. The scorer prints the result without these trades beside the judged one, not judged.")
w(f"- Large overnight move inside the hold, fixed now (replay_11_overnight): a trade is flagged when a close-to-next-open ratio between two days of its hold (entry day to exit day) is below {OV['ratio_min']} or above {OV['ratio_max']}. The judged result keeps every trade; the result without flagged trades is printed beside it, not judged, with the list of flagged trades. Measured on the files to {P['last']}: {Wn['all_large_overnight_moves_in_used_symbols']} such ratios on any day in the used events' stocks; inside a used event's hold: " + ", ".join(f"{h} {v['overnight_flagged_total']}" for h, v in Wn["by_hold"].items()) + ". Held-back H5 holds that run past the last price day and are not yet counted: " + str(Wn["by_hold"]["H5"]["prices_end_first"]) + ". None of the large ratios falls on a split day from the list above. Their causes (earnings gaps before entry, special payouts, deals) were not looked up: UNKNOWN, and not needed while none is inside a hold.")
w("- Price files under a new ticker for the same CIK (closes agree on every shared day, or the old ticker has no bars): " + ", ".join(f"{a} to {b}" for a, b in S["price_aliases"].items()) + ". The rule and the two exceptions are written in `common_11.py`.")
w("- No return after any event has been worked out. The only returns worked out are open-to-5th-close moves in windows that start and end in March 2026, to size the test.\n")
w("## What a reader is shown\n")
w(f"- The instruction in `reader_instruction_11.txt`, the same for every reader, word for word. Then one file per release: its event id (the first 12 characters of the SHA-256 of the accession number), the SHA-256 of the text below it, the acceptance time in New York time and the extracted release text. The header carries no ticker, list, price, chart, news, other filing or estimate. The release text names the company, and in " + pc(tx["share_with_ticker_in_shown_text"]) + " of texts the ticker (as a whole word in the first replay_11_readers.text_cap_chars characters; MEASURED by `prep_11.py summary`).")
w(f"- Text cap: replay_11_readers.text_cap_chars = {cap} characters, cut at the last line break before it, with a note saying it was cut. Measured on the {n(tx['events'])} used texts: median {n(tx['median'])} characters (10th percentile {n(tx['p10'])}, 90th {n(tx['p90'])}); medians by list " + ", ".join(f"{l} {n(v)}" for l, v in tx["by_list"].items()) + f". The cap cuts {pc(tx['share_cut'])} of texts. A line headed outlook or guidance was found in {n(tx['guidance_heading_found'])} texts; its median start is character {n(tx['guidance_heading_median_pos'])} and its 90th percentile {n(tx['guidance_heading_p90_pos'])}. In {pc(tx['share_guidance_heading_after_cap'])} of those it starts after the cap and is lost.")
w("- Other caps considered, share of texts cut and share of guidance headings lost: " + "; ".join(f"{c}: {pc(tx['share_cut_by_candidate_cap'][c])} and {pc(tx['share_guidance_after_by_candidate_cap'][c])}" for c in tx["share_cut_by_candidate_cap"]) + ".")
w("- What gets cut is the end of the text. The headline, the highlights, the chief executive's quote and, in most releases, the guidance come first. The cut part is the financial tables (statements, reconciliations, segment detail) and also non-GAAP definitions, the forward-looking statements notice and the company description; in a few texts it is part of the guidance. So \"the tables at the end are what gets cut\" is only about half true. In the extraction check below, table rows are " + pc(sum(r['table_share_of_part_after_cap'] or 0 for r in X['texts'] if r['share_after_cap'] > 0) / max(1, X['totals']['cut'])) + " of the cut part on average and " + pc(sum(r['table_share_of_part_before_cap'] for r in X['texts']) / len(X['texts'])) + " of the kept part.")
w("- Answer: one JSON line per release with event_id, input_sha256, score (a whole number from -2 to 2) and reason (one line, at most 200 characters, naming what in the release drove the score).")
w("- Buy: a final score of 1 or 2. Skip: 0, -1 or -2. The desk cannot sell short, so -1 and -2 are only skips.\n")
w("## How the readers run, and the gap\n")
w("- The lead can run models only as helper agents, and helpers have tools. Each reader is one helper given one folder of at most replay_11_readers.batch_max = " + str(RD["batch_max"]) + " releases and told, in `READER_BRIEF_11.md`, to read only that folder, write one answers file, and use nothing else.")
w("- Gap: no tools is an instruction, not enforced. A helper could search the web for the stock's move or open another reader's folder, and the checker could not tell from the answers file. Lowered, not removed, by: no ticker in the header (the text itself usually names it, above), folders that hold only prompts, a fresh helper for each folder with no other context, the instruction to say so and score 0 if it remembers the move (the checker sets such an answer to 0, stores the flag and counts it in the results), and the lead looking at the helper's tool calls where the platform shows them.")
w("- The model is not checked either: the folder names the reader and the lead spawns that model. The answers file does not prove which model wrote it.")
w("- `prep_11.py design` writes every prompt once to `~/workspace/rig/data/edgar_11/prompts/` and copies it into one folder per reader per batch: `INSTRUCTION.txt`, `manifest.json` (reader, batch number b001, b002 and so on, the instruction's SHA-256, each event id and text hash; no phase) and `events/`. What each folder must hold is kept outside the reader's folders, in `reading/<phase>/<reader>.expected.json`. Batches are dealt from a seeded shuffle, so each mixes companies and dates, and never holds two releases from one company. Every reader gets the same batches, each in its own seeded order.")
w("- `check_11_answers.py FOLDER` refuses a file with a wrong hash, a missing or unknown or repeated event, a score that is not a whole number from -2 to 2, a bad reason (empty, over 200 characters, or a line break), extra keys, a changed instruction, or a folder copy of a release that differs from the stored prompt. A refused file goes back to the same helper once. After that, `--second-try` sets each answer still missing or bad to 0 and flags it; an event answered twice is set to 0. A changed instruction or release copy is refused even then. A reason that says the reader remembers the move is set to 0, and `remembered` is stored and counted. The pattern is a backstop for the instruction, which already tells the reader to give 0, so both lines are printed: the judged one with these answers set to 0, and beside it, not judged, the same set-up with the scores as given, with the list of event ids that were set to 0. A match with a negation in the three words before it is skipped; a reason under 4 words is stored as `short_reason` and counted. `--collect PHASE` refuses unless every expected reader, folder and event is there (for the held-back `cascade`, the strong reader on exactly the disagreements and the audit), joins the checked folders into one file per reader and writes `answers_11_<phase>_hashes.json` (written for each phase; it does not exist yet).\n")
w("## The design sample and the six set-ups\n")
ds = S["design_sample"]
w(f"- A seeded draw (replay_11_statistics.seed = {ST['seed']}) of replay_11_design.sample_per_list = {DS['sample_per_list']} design-half events from each list, {ds['events']} in all. Every one is read by all three small readers (" + ", ".join(f"`{m}`" for m in RD["small_models"]) + f") and by the strong reader (`{RD['strong_model']}`). That is {ds['folders_per_reader']} folders per reader, {ds['folders_total']} helper runs.")
w("- The set-ups, fixed now, in the order replay_11_design.setups lists them, cheapest first: each small reader alone (3); the strong reader alone; `middle`, the middle of the three small scores; `cascade`, the middle of the three where they agree and the strong reader's score where they disagree. They disagree when their buy-or-skip answers are not all the same, or their scores differ by 2 or more.")
w(f"- Trials: {nsu} set-ups times {nh} holds = {nsu * nh}, plus yardstick (c) at {nh} holds = {nsu * nh + nh} ledger rows (replay_11_statistics.new_trials = {ST['new_trials']}).")
w(f"- Choosing rule, fixed now: on the design sample, the set-up with the highest mean {ST['main_hold']} return after costs minus yardstick (a), among those that buy between replay_11_design.buy_share_min = {pc(DS['buy_share_min'], 0)} and buy_share_max = {pc(DS['buy_share_max'], 0)} of events. Means are compared rounded to 0.01 percentage points; a tie goes to the set-up earlier in the list. If none qualifies, the held-back half is not read and the result is a fail. `score_11.py --design` writes the choice into `results_11_design.json` (written by that run; it does not exist yet).")
w("- Only the chosen set-up reads the held-back half, once, all events. For `cascade` the strong reader reads the disagreements and a seeded replay_11_readers.audit_share = " + pc(RD["audit_share"], 0) + " of the agreed events (the audit is reported, not judged).")
w("- Agreement, reported for the design sample and, where there is more than one reader, the held-back half: share of events where the three small readers agree on buy or skip, Fleiss' kappa on buy or skip, the rank correlation of scores for each pair of the four readers, the share sent to the strong reader, how often the strong reader agrees with the small readers' agreed answer, and each reader's buy share. Low agreement is a result, not a fault.\n")
w("## Trades\n")
w("- Entry: the open of the first regular session after the acceptance time. Before 09:30 on a trading day, that day's open; at or after 09:30, the next trading day's open. In practice a market-on-open order placed before the open, so the reader never sees the open.")
w("- Exits (replay_11_statistics.holds): " + ", ".join(f"{h} sells at the close of trading day {d} counting the entry day as day 1" for h, d in ST["holds"].items()) + f". {ST['main_hold']} is the main test.")
w(f"- Cost per side by list, an assumption fixed now (replay_11_costs.bps_per_side): " + ", ".join(f"{l} {v} bps" for l, v in cost.items()) + ". A buy fills at open times (1 + cost) and a sale at close times (1 - cost). Commission 0. Sensitivities at " + ", ".join(f"{m} times" for m in CO["sensitivity_multiples"]) + " every list's cost are reported, not judged.")
SP = os.path.join(C.DATA, "..", "stock_spreads_measured.md")
if os.path.exists(SP):
    sp = open(SP, encoding="utf-8").read(); r = re.search(r"\| First 30 min \| (\d+) \| ([\d.]+) \| ([\d.]+) \|", sp); ns = re.search(r"all (\d+) symbols pooled", sp)
    w(f"- A check on the assumption, read by this builder from another helper's file on the research machine (`~/workspace/rig/stock_spreads_measured.md`, Alpaca SIP quotes, June to November 2026, {ns.group(1) if ns else 'UNKNOWN'} large stocks and funds): the median half-spread in the first 30 minutes after the open is {r.group(2)} bps and its 90th percentile {r.group(3)} bps, from {r.group(1)} observations (MEASURED by that helper). So {cost['500']} bps for the 500 sits between the two. Nothing was measured for the 400 or the 600, and an opening auction can cost more than the quoted spread: UNKNOWN.")
else:
    w("- The measured spread file `~/workspace/rig/stock_spreads_measured.md` was not on this machine when this was built.")
w("- The prices on file end on " + P["last"] + ". Held-back H5 trades entered after the fifth-last trading day have no exit yet, so prices are collected again before the held-back half is scored. `score_11.py` refuses if the SPY file does not reach the last exit day.")
w("- Equal weight per trade; the result is the mean return per trade after costs. No account curve, because trades overlap.\n")
w("## Yardsticks\n")
w("- (a) Every release: buy every event in the same set (design sample or held-back half), each at its list's cost.")
w(f"- (b) Random picks: replay_11_statistics.draws = {ST['draws']} draws, seeded, each picking without replacement as many events as the set-up bought, from the same set. Reported: the 95th percentile of the draws' means and the share of draws the set-up beat.")
w(f"- (c) Opening jump, no AI: buy when the entry open is more than replay_11_gap.min_up_pct = {GP['min_up_pct']}% above the last close before the filing. It decides on the price it fills at, which the desk could not quite do, so it is a favourable yardstick.")
w("- Reported, not judged: each mean minus SPY's move over the same open-to-close window, and each list alone.\n")
w("## The pass mark (held-back half, all three lists pooled)\n")
w(f"- Pass at a hold: the chosen set-up's buys have a higher mean return after costs than (a), and higher than the 95th percentile of (b), with at least replay_11_statistics.min_buys = {ST['min_buys']} buys. Fewer is \"too few to judge\", not a pass.")
w(f"- {ST['main_hold']} is the main test. A pass at the other hold only is reported as a pass at the second exit and is not enough to start practice trading.")
w("- Each list alone is reported and not judged.")
w("- Only faults in code may be fixed after the design sample is seen. A change to the instruction, the models, the batch size, the cap, the buy threshold, the exits, the costs or the pass mark is a new trial with new ledger rows.")
w("- `score_11.py --heldback` is run once, by the lead. It refuses unless the held-back answer hashes and `results_11_design.json` are in origin/main byte for byte. It refuses if `results_11_heldback.json` or its lock record `score_11_heldback.lock` exists locally or in origin/main; it writes the lock after its checks and before it reads a held-back price, so a deleted output does not let it run again. `--design` refuses if `results_11_design.json` exists locally or in origin/main. Both modes refuse unless this plan is `research_rig/PREREG_11_earnings_release_reader.md` and is in origin/main byte for byte, and the replay_11_* keys in `config/thresholds.yaml` equal those in origin/main; `--heldback` also needs them equal to the keys stored in `results_11_design.json`. The real run reads and writes `research_rig/` and refuses if EDGAR_11_DIR, STOCK_DAILY_11_DIR, SPY_DAILY_11_FILE or RESULTS_11_DIR is set; only the tests set them. Both modes refuse unless the hashes file lists exactly one collected answers file for each reader the set-up needs, and they score only those files. Each result file holds one SHA-256 over the names and bytes of the price files it read, SPY included.")
w("- A pass means worth trying on the practice desk with pretend money. It does not mean it makes money.\n")
